import 'package:flutter_test/flutter_test.dart';import 'package:my_income_manager/src/models/income_models.dart';void main(){test('source and account stay separate',(){final now=DateTime(2026,9,25);final r=IncomeRecord(id:7,amount:12000,date:now,type:IncomeType.dividend,source:'삼성전자',account:'ISA',memo:'test',createdAt:now,updatedAt:now);final restored=IncomeRecord.fromMap(r.toMap());expect(restored.source,'삼성전자');expect(restored.account,'ISA');expect(restored.type,IncomeType.dividend);expect(restored.amount,12000);});test('all initial income types have labels',()=>expect(IncomeType.values.map((e)=>e.label).toSet().length,7));}
